// === Tab: mySketch ===
function setup() {
  createCanvas(4 / 3 * windowHeight, windowHeight, WEBGL);
  setAttributes("alpha", false);
  _bgWidth = max(width, height);
  _minWidth = _bgWidth * 0.8;
  colorMode(HSB, 200, 100, 100, 255);
  noStroke();
  backgroundColor = color(59, 10, 10);
  background(backgroundColor);
  setShape(0, 19, 18, 0);
  //setShape(300, 14, 13, -92);
  //setShape(-300, 13, 12, -88);
}

function setShape(xyOffset, numOfCircles, numOfTile, radiusOffset) {
  let numCircles = numOfCircles; // Increased number of concentric circles
  let numTile = numOfTile; // Initial number of tiles for the outermost circle
  let initRadius = _minWidth / 4 + radiusOffset; // Starting radius for the outermost circle
  let initTileRadius = _minWidth / numTile + radiusOffset; // Significantly increased initial tile radius for more overlap
  let initH = random(360);

  for (let j = 0; j < numCircles; j++) {
    let factor = 1 - j * 0.25; // Adjusted factor for more spacing between circles
    let currentRadius = initRadius * factor; // Adjust circle radius
    let currentTileNum = numTile - j * 2; // Adjust number of tiles so it decreases less rapidly
    let angleStep = TWO_PI / currentTileNum;
    let tileRadius = initTileRadius * (1 - j * 0.03); // Adjusted decrease in tile radius for more overlap
    let angleOffset = j * TWO_PI / numCircles; // Incremental angle offset for each circle, scaled more visibly

    for (let i = 0; i < currentTileNum; i++) {
      let ang = i * angleStep + angleOffset; // Include angle offset
      let centx = currentRadius * cos(ang);
      let centy = currentRadius * sin(ang);
      drawShape(tileRadius, centx + xyOffset, centy + xyOffset, ang, initH);
    }
  }
}

function drawShape(r, centx, centy, ang, initH) {
  let numCorner = 64; // Number of corners for each shape
  let h = random(360);
  push();
  translate(centx, centy);
  rotate(ang + HALF_PI); // Rotate shape to face outwards
  beginShape();
  for (let i = 0; i < numCorner; i++) {
    if (i == 0) { fill(initH, 100, 100); }
    if (i != 0) { fill(h, 100, 100, 0); }
    vertex(r * cos(2 * PI / numCorner * i), r * sin(2 * PI / numCorner * i));
  }
  endShape(CLOSE);
  pop();
}

let lapse = 0; // mouse timer
function mousePressed() {
  // prevents mouse press from registering twice
  if (millis() - lapse > 400) {
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
      ".jpg");
    lapse = millis();
  }
}

